import os
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Tuple

import boto3


def _to_utc_datetime(value: Any) -> datetime:
    if isinstance(value, datetime):
        return value.astimezone(timezone.utc) if value.tzinfo else value.replace(tzinfo=timezone.utc)
    if isinstance(value, (int, float)):
        return datetime.fromtimestamp(value, tz=timezone.utc)
    if isinstance(value, str):
        text = value.strip()
        if text.endswith("Z"):
            text = text[:-1] + "+00:00"
        dt = datetime.fromisoformat(text)
        return dt.astimezone(timezone.utc) if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    raise TypeError("start_time/end_time must be datetime, ISO8601 string, or unix timestamp")


def _normalize_dimensions(dimensions: Optional[Dict[str, str]]) -> List[Dict[str, str]]:
    if not dimensions:
        return []
    return [{"Name": str(k), "Value": str(v)} for k, v in sorted(dimensions.items())]


def _build_metric_stat(
    metric_name: str,
    namespace: str,
    dimensions: Optional[Dict[str, str]],
    stat: str,
    period: int,
    unit: Optional[str],
) -> Dict[str, Any]:
    metric = {
        "Namespace": namespace,
        "MetricName": metric_name,
        "Dimensions": _normalize_dimensions(dimensions),
    }
    metric_stat = {
        "Metric": metric,
        "Period": int(period),
        "Stat": stat,
    }
    if unit:
        metric_stat["Unit"] = unit
    return metric_stat


def _extract_series(result: Dict[str, Any]) -> List[Tuple[datetime, float]]:
    timestamps = result.get("Timestamps", [])
    values = result.get("Values", [])
    pairs = [(ts, val) for ts, val in zip(timestamps, values) if val is not None]
    pairs.sort(key=lambda item: item[0])
    return pairs


def _aggregate(values: List[float], method: str) -> Optional[float]:
    if not values:
        return None
    method = method.lower()
    if method == "avg":
        return sum(values) / len(values)
    if method == "sum":
        return sum(values)
    if method == "min":
        return min(values)
    if method == "max":
        return max(values)
    if method == "latest":
        return values[-1]
    raise ValueError("aggregate must be one of: avg, sum, min, max, latest")


def compare_cloudwatch_metric(
    metric_name: str,
    namespace: str,
    start_time: Any,
    end_time: Any,
    left_dimensions: Optional[Dict[str, str]],
    right_dimensions: Optional[Dict[str, str]],
    stat: str = "Average",
    period: int = 300,
    aggregate: str = "avg",
    unit: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    start_dt = _to_utc_datetime(start_time)
    end_dt = _to_utc_datetime(end_time)

    if end_dt <= start_dt:
        raise ValueError("end_time must be greater than start_time")

    client = boto3.client(
        "cloudwatch",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
    )

    response = client.get_metric_data(
        StartTime=start_dt,
        EndTime=end_dt,
        MetricDataQueries=[
            {
                "Id": "leftq",
                "ReturnData": True,
                "MetricStat": _build_metric_stat(metric_name, namespace, left_dimensions, stat, period, unit),
            },
            {
                "Id": "rightq",
                "ReturnData": True,
                "MetricStat": _build_metric_stat(metric_name, namespace, right_dimensions, stat, period, unit),
            },
        ],
        ScanBy="TimestampAscending",
    )

    results = {item["Id"]: item for item in response.get("MetricDataResults", [])}
    left_series = _extract_series(results.get("leftq", {}))
    right_series = _extract_series(results.get("rightq", {}))

    left_values = [v for _, v in left_series]
    right_values = [v for _, v in right_series]

    left_agg = _aggregate(left_values, aggregate)
    right_agg = _aggregate(right_values, aggregate)

    difference = None
    ratio = None
    percent_difference = None

    if left_agg is not None and right_agg is not None:
        difference = left_agg - right_agg
        if right_agg != 0:
            ratio = left_agg / right_agg
            percent_difference = (difference / right_agg) * 100.0

    return {
        "provider": "amazon-cloudwatch",
        "region": client.meta.region_name,
        "metric": {
            "namespace": namespace,
            "name": metric_name,
            "stat": stat,
            "period": int(period),
            "unit": unit,
        },
        "window": {
            "start_time": start_dt.isoformat(),
            "end_time": end_dt.isoformat(),
        },
        "left": {
            "dimensions": left_dimensions or {},
            "points": [{"timestamp": ts.isoformat(), "value": val} for ts, val in left_series],
            "aggregate": aggregate,
            "aggregate_value": left_agg,
        },
        "right": {
            "dimensions": right_dimensions or {},
            "points": [{"timestamp": ts.isoformat(), "value": val} for ts, val in right_series],
            "aggregate": aggregate,
            "aggregate_value": right_agg,
        },
        "comparison": {
            "difference": difference,
            "ratio": ratio,
            "percent_difference": percent_difference,
        },
    }
